        --color-primary:      #2563eb;
        --color-primary-dark: #1d4ed8;
        --color-error:        #dc2626;
        --color-error-bg:     #fef2f2;
        --color-error-border: #fca5a5;
        --color-success:      #15803d;
        --color-success-bg:   #f0fdf4;
        --radius-sm:          6px;
        --radius-md:          12px;
        --radius-lg:          16px;
        --shadow-card:        0 1px 3px rgba(0,0,0,.06), 0 8px 32px rgba(0,0,0,.08);
        --font-sans:          system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      }

      html { font-size: 16px; }

      body {
        font-family: var(--font-sans);
        background: var(--color-bg);
        color: var(--color-text);
        min-height: 100dvh;
        display: grid;
        place-items: center;
        padding: 1.5rem;
      }

      /* ─── Skip link ────────────────────────────────────────────────── */
      .skip-link {
        position: absolute;
        top: -100%;
        left: 1rem;
        background: var(--color-primary);
        color: #fff;
        padding: .5rem 1rem;
        border-radius: var(--radius-sm);
        font-weight: 600;
        text-decoration: none;
        z-index: 100;
        transition: top .1s;
      }
      .skip-link:focus { top: 1rem; }

      /* ─── Card ─────────────────────────────────────────────────────── */
      .card {
        background: var(--color-surface);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow-card);
        padding: 2.5rem 2rem;
        width: 100%;
        max-width: 480px;
      }

      /* ─── Header ───────────────────────────────────────────────────── */
      .card-header { margin-bottom: 1.75rem; }

      .card-eyebrow {
        font-size: .75rem;
        font-weight: 600;
        letter-spacing: .08em;
        text-transform: uppercase;
        color: var(--color-primary);
        margin-bottom: .5rem;
      }

      h1 {
        font-size: 1.5rem;
        font-weight: 700;
        line-height: 1.25;
        color: var(--color-text);
      }

      .card-description {
        margin-top: .625rem;
        font-size: .9375rem;
        color: var(--color-text-muted);
        line-height: 1.6;
      }

      /* ─── Divider ──────────────────────────────────────────────────── */
      hr {
        border: none;
        border-top: 1px solid var(--color-border);
        margin: 1.5rem 0;
      }

      /* ─── Form ─────────────────────────────────────────────────────── */
      form { display: flex; flex-direction: column; gap: 1.5rem; }

      /* Required legend */
      .required-note {
        font-size: .8125rem;
        color: var(--color-text-muted);
      }
      .required-note span[aria-hidden] { color: var(--color-error); margin-right: .25rem; }

      /* ─── form-field ───────────────────────────────────────────────── */
      .form-field {
        display: flex;
        flex-direction: column;
        gap: .5rem;
      }

      /* Checkbox row */
      .checkbox-row {
        display: flex;
        align-items: flex-start;
        gap: .75rem;
        padding: 1rem;
        border: 1.5px solid var(--color-border);
        border-radius: var(--radius-md);
        background: #fafafa;
        cursor: pointer;
        transition: border-color .15s, background .15s;
      }
      .checkbox-row:has(input:focus-visible) {
        border-color: var(--color-border-focus);
        outline: 2px solid var(--color-border-focus);
        outline-offset: 2px;
        background: #eff6ff;
      }
      .form-field.has-error .checkbox-row {
        border-color: var(--color-error-border);
        background: var(--color-error-bg);
      }

      /* Native checkbox – styled but accessible */
      input[type="checkbox"] {
        flex-shrink: 0;
        width: 1.125rem;
        height: 1.125rem;
        margin-top: .15rem;           /* optical align with label cap-height */
        accent-color: var(--color-primary);
        cursor: pointer;
      }
      /* Explicit focus ring for browsers that don't use accent-color for focus */
      input[type="checkbox"]:focus-visible {
        outline: 2px solid var(--color-border-focus);
        outline-offset: 2px;
      }

      label[for="agree-terms"] {
        font-size: .9375rem;
        line-height: 1.55;
        cursor: pointer;
        color: var(--color-text);
      }
      label[for="agree-terms"] .required-asterisk {
        color: var(--color-error);
        margin-left: .15rem;
      }
      label[for="agree-terms"] a {
        color: var(--color-primary);
        text-decoration: underline;
        text-underline-offset: .15em;
      }
      label[for="agree-terms"] a:hover { color: var(--color-primary-dark); }
      label[for="agree-terms"] a:focus-visible {
        outline: 2px solid var(--color-border-focus);
        outline-offset: 2px;
        border-radius: 2px;
      }

      /* Helper text */
      .helper-text {
        font-size: .8125rem;
        color: var(--color-text-muted);
        padding-left: .25rem;
        line-height: 1.5;
      }

      /* Error text */
      .error-text {
        font-size: .8125rem;
        font-weight: 500;
        color: var(--color-error);
        display: flex;
        align-items: center;
        gap: .375rem;
        padding-left: .25rem;
      }
      .error-text[hidden] { display: none; }
      .error-text svg { flex-shrink: 0; }

      /* ─── Submit button ────────────────────────────────────────────── */
      button[type="submit"] {
        width: 100%;
        padding: .8125rem 1.5rem;
        font-family: inherit;
        font-size: 1rem;
        font-weight: 600;
        color: #fff;
        background: var(--color-primary);
        border: none;
        border-radius: var(--radius-md);
        cursor: pointer;
        transition: background .15s, box-shadow .15s, transform .1s;
        letter-spacing: .01em;
      }
      button[type="submit"]:hover  { background: var(--color-primary-dark); }
      button[type="submit"]:active { transform: scale(.98); }
      button[type="submit"]:focus-visible {
        outline: 2px solid var(--color-border-focus);
        outline-offset: 3px;
      }

      /* ─── Status message ───────────────────────────────────────────── */
      .status-message {
        font-size: .9375rem;
        font-weight: 500;
        padding: .875rem 1rem;
        border-radius: var(--radius-sm);
        display: flex;
        align-items: center;
        gap: .5rem;
      }
      .status-message[hidden] { display: none; }
      .status-message--success {
        color: var(--color-success);
        background: var(--color-success-bg);
        border: 1px solid #bbf7d0;
      }

      /* ─── Forced colors (high-contrast mode) ───────────────────────── */
      @media (forced-colors: active) {
        .checkbox-row { border: 2px solid ButtonText; }
        button[type="submit"] { border: 2px solid ButtonText; }
      }

      /* ─── Reduced motion ───────────────────────────────────────────── */
      @media (prefers-reduced-motion: reduce) {
        *, *::before, *::after { transition: none !important; }
      }
    </style>
  </head>
  <body>

    <!-- Skip navigation -->
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <div class="card">

        <!-- CardHeader component -->
        <header class="card-header">
          <p class="card-eyebrow">Legal agreement</p>
          <h1>Terms of Use</h1>
          <p class="card-description">
            Before you continue, please review and accept our Terms of Use.
            This covers how you may use the service, your rights, and our
            responsibilities to you.
          </p>
        </header>

        <hr />

        <!-- ConsentForm component -->
        <form id="consent-form" novalidate aria-label="Terms of use agreement">

          <p class="required-note">
            <span aria-hidden="true">*</span> Required field
          </p>

          <!-- FormField component -->
          <div class="form-field" id="field-agree">

            <label class="checkbox-row" for="agree-terms">
              <input
                type="checkbox"
                id="agree-terms"
                name="agree-terms"
                required
                aria-describedby="agree-help agree-error"
              />
              <span>
                I have read and agree to the
                <a href="#terms-modal" id="terms-link">Terms of Use</a>
                <span class="required-asterisk" aria-hidden="true">*</span>
              </span>
            </label>

            <p id="agree-help" class="helper-text">
              You must accept the Terms of Use to create an account and access the service.
            </p>

            <p id="agree-error" class="error-text" hidden role="alert">
              <!-- error icon -->
              <svg aria-hidden="true" focusable="false" width="14" height="14" viewBox="0 0 16 16" fill="currentColor">
                <path d="M8 1a7 7 0 1 0 0 14A7 7 0 0 0 8 1ZM7.25 4.75a.75.75 0 0 1 1.5 0v3.5a.75.75 0 0 1-1.5 0v-3.5Zm.75 7a.875.875 0 1 1 0-1.75.875.875 0 0 1 0 1.75Z"/>
              </svg>
              Error: You must agree to the Terms of Use to continue.
            </p>

          </div>

          <!-- StatusMessage component -->
          <p
            id="form-status"
            class="status-message status-message--success"
            aria-live="polite"
            aria-atomic="true"
            hidden
          >
            <!-- success icon -->
            <svg aria-hidden="true" focusable="false" width="16" height="16" viewBox="0 0 16 16" fill="currentColor">
              <path d="M8 1a7 7 0 1 0 0 14A7 7 0 0 0 8 1Zm3.03 5.47-3.5 3.5a.75.75 0 0 1-1.06 0l-1.5-1.5a.75.75 0 1 1 1.06-1.06l.97.97 2.97-2.97a.75.75 0 0 1 1.06 1.06Z"/>
            </svg>
            You've successfully agreed to the Terms of Use.
          </p>

          <button type="submit">Accept and Continue</button>

        </form>
        <!-- /ConsentForm -->

      </div>
    </main>

    <script>
      // ConsentForm controller
      (function () {
        var form      = document.getElementById('consent-form');
        var checkbox  = document.getElementById('agree-terms');
        var formField = document.getElementById('field-agree');
        var errorEl   = document.getElementById('agree-error');
        var statusEl  = document.getElementById('form-status');

        function showError() {
          formField.classList.add('has-error');
          checkbox.setAttribute('aria-invalid', 'true');
          errorEl.removeAttribute('hidden');
        }

        function clearError() {
          formField.classList.remove('has-error');
          checkbox.removeAttribute('aria-invalid');
          errorEl.setAttribute('hidden', '');
        }

        function showSuccess() {
          statusEl.removeAttribute('hidden');
        }

        // Clear error as soon as the user checks the box
        checkbox.addEventListener('change', function () {
          if (checkbox.checked) clearError();
        });

        form.addEventListener('submit', function (e) {
          e.preventDefault();

          // Hide any previous success banner
          statusEl.setAttribute('hidden', '');

          if (!checkbox.checked) {
            showError();
            checkbox.focus();
            return;
          }

          clearError();
          showSuccess();
          // In a real app, proceed with form submission here.
        });
      }());
    </script>

  </body>
</html>
