      .checkbox-row {
        display: flex;
        align-items: flex-start;
        gap: .75rem;
        padding: 1rem;
        border: 1.5px solid var(--color-border);
        border-radius: var(--radius-md);
        background: #fafafa;
        cursor: pointer;
        transition: border-color .15s, background .15s;
