      }
      label[for="agree-terms"] a {
        color: var(--color-primary);
        text-decoration: underline;
        text-underline-offset: .15em;
      }
      label[for="agree-terms"] a:hover { color: var(--color-primary-dark); }
      label[for="agree-terms"] a:focus-visible {
        outline: 2px solid var(--color-border-focus);
        outline-offset: 2px;
        border-radius: 2px;
      }

      /* Helper text */
      .helper-text {
        font-size: .8125rem;
        color: var(--color-text-muted);
        padding-left: .25rem;
        line-height: 1.5;
