        font-size: .8125rem;
        font-weight: 500;
        color: var(--color-error);
        display: flex;
        align-items: center;
        gap: .375rem;
        padding-left: .25rem;
      }
      .error-text[hidden] { display: none; }
      .error-text svg { flex-shrink: 0; }

      /* ─── Submit button ────────────────────────────────────────────── */
      button[type="submit"] {
        width: 100%;
        padding: .8125rem 1.5rem;
        font-family: inherit;
        font-size: 1rem;
        font-weight: 600;
        color: #fff;
        background: var(--color-primary);
